# area: callables
# hypothesis: A callback protocol with a keyword-only parameter accepts a function whose keyword-only parameter has a default, rejects a positional-only function, and at runtime the positional-only callback raises TypeError on a keyword call.
from typing import Callable, Protocol, TypeVar, reveal_type

T = TypeVar('T')


class KwCallback(Protocol):
    def __call__(self, *, label: str, n: int) -> str: ...


def with_default(*, label: str, n: int = 1) -> str:
    return label * n


def positional_only(label: str, n: int, /) -> str:
    return label * n


def repeat_each(f: Callable[[T], T]) -> Callable[[list[T]], list[T]]:
    def apply(xs: list[T]) -> list[T]:
        return [f(x) for x in xs]
    return apply


def call_kw(cb: KwCallback) -> str:
    return cb(label='ab', n=2)


def bump(v: int) -> int:
    return v + 1


kw_ok: KwCallback = with_default
reveal_type(kw_ok)
bad: KwCallback = positional_only  # expect-error
print(call_kw(kw_ok))
print(with_default(label='z'))
print(positional_only('q', 3))
print(repeat_each(bump)([1, 2, 3]))
try:
    print(call_kw(bad))
except TypeError:
    print('positional-only callback: TypeError at runtime')
